  disc:[["Pourquoi ne peut-on pas deviner ce qu'une personne vit ?","Parce que beaucoup de choses importantes sont invisibles."],
   ["Comment poser une question sur une différence avec respect ?","Demander à la personne elle-même, en privé, et accepter qu'elle ne veuille pas répondre."],
   ["Que faire si on voit quelqu'un se faire moquer ?","Ne pas rire, aller vers la personne visée, et prévenir un adulte."]],
